const CLUSTER_CENTERS = [
  { x: 22, y: 50, color: "#4ADE80", label: "Positive" },
  { x: 50, y: 52, color: "#FFD93D", label: "Neutral" },
  { x: 78, y: 50, color: "#FF4A6B", label: "Negative" },
];

const Scene4Clustering: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  // Tags animate in then drift toward cluster centers
  const tagStartPositions = [
    { x: 15, y: 20 }, { x: 75, y: 18 }, { x: 30, y: 80 }, { x: 68, y: 78 },
    { x: 10, y: 52 }, { x: 88, y: 30 }, { x: 45, y: 15 }, { x: 55, y: 82 },
    { x: 20, y: 68 }, { x: 80, y: 65 }, { x: 40, y: 25 }, { x: 62, y: 38 },
    { x: 25, y: 42 },
  ];

  return (
    <AbsoluteFill
      style={{
        fontFamily: "'Inter', sans-serif",
        backgroundColor: COLORS.bg,
        overflow: "hidden",
      }}
    >
      {/* Cluster orb glows */}
      {CLUSTER_CENTERS.map((c, i) => {
        const orbP = spring({ frame, fps: vfps, delay: 30 + i * 10, config: { damping: 200 } });
        return (
          <div key={i} style={{
            position: "absolute",
            left: `${c.x}%`,
            top: `${c.y}%`,
            transform: "translate(-50%, -50%)",
            width: interpolate(orbP, [0, 1], [0, 320]),
            height: interpolate(orbP, [0, 1], [0, 320]),
            borderRadius: "50%",
            background: `radial-gradient(circle, ${c.color}18 0%, ${c.color}06 50%, transparent 70%)`,
            border: `1.5px solid ${c.color}25`,
            opacity: orbP,
          }} />
        );
      })}

      {/* Cluster labels */}
      {CLUSTER_CENTERS.map((c, i) => {
        const labelP = spring({ frame, fps: vfps, delay: 35 + i * 10, config: { damping: 200 } });
        return (
          <div key={i} style={{
            position: "absolute",
            left: `${c.x}%`,
            top: `${c.y - 14}%`,
            transform: "translate(-50%, -50%)",
            opacity: labelP,
            fontSize: 22,
            fontWeight: 800,
            color: c.color,
            textShadow: `0 0 20px ${c.color}60`,
            letterSpacing: "-0.01em",
            whiteSpace: "nowrap",
          }}>
            {c.label}
          </div>
        );
      })}

      {/* Tags */}
      {CLUSTER_TAGS.map((tag, i) => {
        const center = CLUSTER_CENTERS[tag.ci];
        const start = tagStartPositions[i % tagStartPositions.length];
        const appearDelay = 4 + i * 5;
        const moveDelay = appearDelay + 8;

        const appearP = spring({ frame, fps: vfps, delay: appearDelay, config: { damping: 200 } });
        const moveP = spring({ frame, fps: vfps, delay: moveDelay, config: { damping: 120 } });

        const currentX = interpolate(moveP, [0, 1], [start.x, center.x + (i % 3 - 1) * 7]);
        const currentY = interpolate(moveP, [0, 1], [start.y, center.y + (Math.floor(i / 3) % 3 - 1) * 7]);
        const floatY = Math.sin(frame * 0.04 + i) * 3;

        return (
          <div key={i} style={{
            position: "absolute",
            left: `${currentX}%`,
            top: `${currentY + floatY * (1 - moveP)}%`,
            transform: "translate(-50%, -50%)",
            opacity: interpolate(appearP, [0, 1], [0, 0.88]),
            backgroundColor: `${center.color}12`,
            border: `1.5px solid ${center.color}35`,
            borderRadius: 10,
            padding: "6px 16px",
            fontSize: 15,
            fontWeight: 600,
            color: center.color,
            whiteSpace: "nowrap" as const,
            boxShadow: `0 0 16px ${center.color}20`,
          }}>
            {tag.text}
          </div>
        );
      })}

      {/* Top status */}
      {(() => {
        const lp = spring({ frame, fps: vfps, delay: 2, config: { damping: 200 } });
        return (
          <div style={{
            position: "absolute",
            top: 80,
            left: 300,
